package com.bts.viewplustest.link; import com.bts.viewplustest.user.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="video_links") public class VideoLink { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="owner_user_id") private User owner; @Column(nullable=false,length=120) private String title; @Column(nullable=false,length=2048) private String url; @Column(nullable=false) private Instant createdAt=Instant.now(); protected VideoLink(){} public VideoLink(User o,String t,String u){owner=o;title=t;url=u;} public Long getId(){return id;}public User getOwner(){return owner;}public String getTitle(){return title;}public String getUrl(){return url;} }
